using System;using System.IO;using System.Collections.Generic;using System.Text.Json;using NeonSyndicate;using NeonSyndicate.Tests;using UnityEngine;
public static class HeartExportFR01 {
 static object V(Vector3 p){return new[]{p.x,p.y,p.z};}
 public static void Main(){CityLayout l=new CityLayout(61724);l.Generate();List<VenueBinding04C> vs=InhabitedCityBindings04C.Select(l,InhabitedCityBindings04CTests.ReadCatalog());l.ApplyProfile04O(CityRevision04O.GothicCivicH5,vs);List<object> venues=new List<object>(),buildings=new List<object>(),routes=new List<object>(),walks=new List<object>(),parts=new List<object>();
 foreach(VenueBinding04C v in vs)venues.Add(new{id=v.Definition.Id,origin=V(v.Origin),outside=V(v.Outside),yaw=v.Yaw,width=v.Width,depth=v.Depth,seed=v.Building.Seed});
 foreach(VenueBinding04C v in vs)foreach(ArtPlacementH2 part in GothicCivicH5.Replaces(v.Definition.Id)?GothicCivicH5.Plan(v):GothicHeartH3.ServicePlan(v))parts.Add(new{owner=v.Definition.Id,model=part.Model,position=V(InhabitedCityBindings04C.LocalToWorld(v.Origin,v.Yaw,part.Position)),yaw=v.Yaw+part.Yaw,scale=V(part.Scale)});
 foreach(ArtPlacementH2 part in GothicHeartH3.CourtPlan(l))parts.Add(new{owner="court",model=part.Model,position=V(part.Position),yaw=part.Yaw,scale=V(part.Scale)});
 foreach(Block b in l.Blocks)foreach(Lot lot in b.Lots)foreach(Building x in lot.Buildings)if(Math.Abs(x.Footprint.CenterX)<180&&x.Footprint.CenterZ>-120&&x.Footprint.CenterZ<200)buildings.Add(new{seed=x.Seed,family=x.GothicFamily04OB,rect=new[]{x.Footprint.X0,x.Footprint.Z0,x.Footprint.X1,x.Footprint.Z1},height=x.Height,roof=x.Roof.ToString(),protectedRoof=x.RoofPad04OB,poi=lot.PoiName});
 foreach(RealmRoute04OB route in l.RealmRoutes04OB){List<object> ps=new List<object>();foreach(Vector3 p in route.Points)ps.Add(V(p));routes.Add(new{id=route.Id,width=route.Width,points=ps});}
 foreach(WalkNode n in l.WalkNodes)if(Math.Abs(n.Pos.x)<170&&n.Pos.z>-120&&n.Pos.z<200)walks.Add(V(n.Pos));
 Vector3 gate;float gateYaw;bool gateReady=HeartPlanFR01.Gate(l,out gate,out gateYaw);List<int> eligible=new List<int>();foreach(Block block in l.Blocks)foreach(Lot lot in block.Lots)foreach(Building b in lot.Buildings)if(HeartPlanFR01.Eligible(l,b))eligible.Add(b.Seed);
 File.WriteAllText("Docs/FantasyRenaissance/FR01/source-plan.json",JsonSerializer.Serialize(new{gate=new{ready=gateReady,position=V(gate),yaw=gateYaw},eligible_buildings=eligible,seed=l.Seed,revision=(int)l.Revision04O,court=V(l.RealmCourt04OB),lens=V(l.HearthLensH3),venues=venues,buildings=buildings,routes=routes,walks=walks,art_parts=parts,receipts=new[]{l.DataChipSpots.ConvertAll(V),l.CrystalShardSpots.ConvertAll(V),l.SpellStoneSpots.ConvertAll(V),l.PickupSpots.ConvertAll(V)},native_unity="NOT RUN"},new JsonSerializerOptions{WriteIndented=true}));}}
